<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { eliminar, exportar, guardar, listar } from '../services/comunicaciones'
import type { CommunicationItem, CommunicationResource } from '../interfaces/comunicaciones.interface'
type Group='noticias'|'publicaciones'|'relaciones'|'configuracion'
const props=defineProps<{group:Group}>()
const groupData={noticias:{title:'Noticias',description:'Registra noticias, temáticas, medios relacionados y documentos.',tabs:[['noticias','Noticias']]},publicaciones:{title:'Publicaciones',description:'Gestiona las publicaciones institucionales y sus archivos.',tabs:[['publicaciones','Publicaciones']]},relaciones:{title:'Relaciones y reuniones',description:'Centraliza stakeholders, reuniones, agendas y acuerdos.',tabs:[['stakeholders','Stakeholders'],['reuniones','Reuniones'],['agendas','Agendas'],['acuerdos','Acuerdos']]},configuracion:{title:'Configuración de comunicaciones',description:'Administra los catálogos utilizados por el módulo.',tabs:[['tematicas','Temáticas'],['medios','Medios'],['tipos-noticia','Tipos de noticia'],['tipos-publicacion','Tipos de publicación'],['tipos-stakeholder','Tipos de stakeholder'],['tipos-medio','Tipos de medio'],['estados-medio','Estados de medio']]}} as const
const data=computed(()=>groupData[props.group]),resource=ref<CommunicationResource>(data.value.tabs[0][0]),items=ref<CommunicationItem[]>([]),search=ref(''),loading=ref(false),saving=ref(false),modal=ref(false),error=ref(''),success=ref(''),editing=ref<number|null>(null),file=ref<File|null>(null)
const form=reactive({codigo:'',titulo:'',nombre:'',descripcion:'',fecha:'',estado:'activo',tipo_id:0,medio_id:0,stakeholder_id:0})
const isCatalog=computed(()=>props.group==='configuracion'),isDocument=computed(()=>resource.value==='noticias'||resource.value==='publicaciones'||resource.value==='reuniones'||resource.value==='acuerdos')
async function load(){loading.value=true;error.value='';try{items.value=await listar(resource.value,search.value)}catch(cause){error.value=message(cause)}finally{loading.value=false}}
function select(value:string){resource.value=value as CommunicationResource;search.value=''}
function open(item?:CommunicationItem){editing.value=item?.id||null;Object.assign(form,{codigo:item?.codigo||'',titulo:item?.titulo||'',nombre:item?.nombre||'',descripcion:item?.descripcion||'',fecha:item?.fecha||'',estado:item?.estado||'activo',tipo_id:0,medio_id:0,stakeholder_id:0});file.value=null;modal.value=true}
function pick(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]||null}
async function save(){if(!(form.nombre||form.titulo||form.descripcion).trim()){error.value='Ingrese el nombre, título o descripción.';return}saving.value=true;try{let payload:FormData|Record<string,unknown>={...form};if(file.value){const fd=new FormData();Object.entries(form).forEach(([key,value])=>fd.append(key,String(value)));fd.append('archivo',file.value);payload=fd}await guardar(resource.value,editing.value,payload);success.value='Registro guardado correctamente.';modal.value=false;await load()}catch(cause){error.value=message(cause)}finally{saving.value=false}}
async function remove(item:CommunicationItem){if(!confirm('¿Eliminar este registro?'))return;try{await eliminar(resource.value,item.id);await load()}catch(cause){error.value=message(cause)}}
function message(cause:unknown){return cause instanceof Error?cause.message:'No se pudo completar la operación.'}
watch(resource,load);onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Institucional / Comunicaciones / {{data.title}}</nav><header class="hero"><div class="mark">COM</div><div><small>AURA · Comunicaciones</small><h1>{{data.title}}</h1><p>{{data.description}}</p></div><button @click="open()">+ Nuevo registro</button></header><div v-if="data.tabs.length>1" class="tabs"><button v-for="tab in data.tabs" :key="tab[0]" :class="{active:resource===tab[0]}" @click="select(tab[0])">{{tab[1]}}</button></div><p v-if="success" class="flash">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><section class="tools"><input v-model.trim="search" placeholder="Buscar por código, nombre o descripción…" @keyup.enter="load"><button @click="load">Buscar</button><button v-if="!isCatalog" class="export" @click="exportar(resource)">Exportar PDF</button></section><div v-if="loading" class="empty">Cargando información…</div><div v-else-if="!items.length" class="empty">No se encontraron registros.</div><section v-else class="table"><header><span>Registro</span><span>Fecha / tipo</span><span>Estado</span><span>Acciones</span></header><article v-for="item in items" :key="item.id"><div><small>#{{item.codigo||item.id}}</small><b>{{item.titulo||item.nombre||item.descripcion}}</b><p v-if="item.titulo||item.nombre">{{item.descripcion}}</p></div><div><b>{{item.fecha||item.tipo||'—'}}</b><small>{{item.medio||item.stakeholder}}</small></div><em>{{item.estado||'Activo'}}</em><footer><button @click="open(item)">Editar</button><button class="delete" @click="remove(item)">Eliminar</button></footer></article></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>{{resource}}</small><h2>{{editing?'Editar':'Registrar'}} registro</h2></div><button type="button" @click="modal=false">×</button></header><label v-if="!isCatalog">Código<input v-model.trim="form.codigo"></label><label v-if="resource==='noticias'||resource==='publicaciones'">Título *<input v-model.trim="form.titulo"></label><label v-else>Nombre *<input v-model.trim="form.nombre"></label><label v-if="!isCatalog">Fecha<input v-model="form.fecha" type="date"></label><label>Descripción<textarea v-model.trim="form.descripcion" rows="4"/></label><label>Estado<select v-model="form.estado"><option value="activo">Activo</option><option value="pendiente">Pendiente</option><option value="finalizado">Finalizado</option><option value="inactivo">Inactivo</option></select></label><label v-if="isDocument">Archivos<input type="file" multiple @change="pick"></label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#7257c8;color:#35464e}nav{margin-bottom:17px;color:#98a4aa;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.62rem;font-weight:700}.hero small,.modal small,.table small{color:var(--accent);font-size:.55rem;font-weight:700;text-transform:uppercase}.hero h1{margin:2px 0;font-size:1.35rem}.hero p{margin:0;color:#7d898f;font-size:.7rem}.hero>button,.tools button,.modal footer button{margin-left:auto;padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.59rem}.tabs{margin-top:14px;display:flex;gap:5px;overflow:auto}.tabs button{padding:8px 11px;border:1px solid #ddd7ed;border-radius:7px;background:#fff;color:#68757c;font-size:.58rem;white-space:nowrap}.tabs button.active{color:#fff;background:var(--accent)}.flash{padding:10px;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.65rem}.flash.error{color:#a13f43;background:#fff0f0}.tools{margin-top:13px;padding:11px;display:flex;gap:6px;border:1px solid #e0e5e8;border-radius:9px;background:#fff}.tools input{flex:1}.tools button{margin-left:0}.tools .export{color:var(--accent);border:1px solid var(--accent);background:#fff}.table{margin-top:12px;border:1px solid #e0e5e8;border-radius:9px;background:#fff;overflow:hidden}.table>header,.table>article{padding:10px 13px;display:grid;grid-template-columns:2fr 1fr 90px 120px;align-items:center;gap:10px}.table>header{color:#fff;background:var(--accent);font-size:.56rem;font-weight:700}.table>article{border-bottom:1px solid #edf0f2}.table b,.table p{display:block;margin:2px 0;font-size:.61rem}.table p,.table article>div:nth-child(2) small{color:#7d898f}.table em{padding:4px 7px;border-radius:10px;background:#eeeafa;font-size:.5rem;font-style:normal;text-align:center}.table footer{display:flex}.table footer button{border:0;color:var(--accent);background:none;font-size:.55rem}.table footer .delete{color:#b44747}.empty{margin-top:13px;padding:50px;text-align:center;border:1px dashed #ccd5da;border-radius:9px;background:#fff;font-size:.67rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,520px);max-height:90vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0 15px;font-size:1rem}.modal header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal label{display:block;margin-bottom:11px;font-size:.61rem}input,select,textarea{width:100%;padding:9px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.65rem}.modal footer{display:flex;justify-content:flex-end;gap:6px}.clear{color:#68757c!important;background:#edf1f3!important}@media(max-width:800px){.hero{flex-wrap:wrap}.hero>button{margin-left:0}.table>header{display:none}.table>article{grid-template-columns:1fr}.tools{flex-wrap:wrap}.tools input{flex-basis:100%}}
</style>
